"""CPU inference using the checkpoint's exported Clef loader and decision head."""
import importlib.util
import json
import sys
from pathlib import Path
import torch
from workflow import QUESTION


class StudentRiskModel:
    def __init__(self, checkpoint, *, device='cpu'):
        checkpoint = Path(checkpoint).resolve()
        # This loader is generated by Unsloth alongside the weights during export.
        spec = importlib.util.spec_from_file_location('student_risk_clef', checkpoint / 'joint_schema_model.py')
        self.clef = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = self.clef
        # Loading a checkpoint must not add interpreter bytecode to its artifact tree.
        previous_write_bytecode = sys.dont_write_bytecode
        sys.dont_write_bytecode = True
        try:
            spec.loader.exec_module(self.clef)
        finally:
            sys.dont_write_bytecode = previous_write_bytecode
        self.model, self.processor = self.clef.load_release_model(
            checkpoint, device=device, dtype=torch.float32, local_files_only=True,
            attn_implementation='sdpa')
        self.config = json.loads((checkpoint / 'unsloth_decision_config.json').read_text())
        # The export folds the head temperature into its weights. Residual calibration
        # is still applied by Unsloth at serving time and must also be applied here.
        self.temperature = self.config['temperature'][2] * self.config.get('head_temperature', 1.0)

    @torch.inference_mode()
    def probability(self, state):
        return self.probabilities([state])[0]

    @torch.inference_mode()
    def probabilities(self, states, batch_size=32):
        device = next(self.model.parameters()).device
        probabilities = []
        for start in range(0, len(states), batch_size):
            records = [self.clef.encode_record(self.processor.tokenizer,
                {'state': state, 'questions': QUESTION}, max_length=self.config['max_len'],
                processor=self.processor) for state in states[start:start + batch_size]]
            batch = self.clef.collate_records(records, self.processor.tokenizer.pad_token_id, device)
            logits = torch.stack([row[0] for row in self.model(batch)])
            positive = [record.questions[0].option_ids.index('true') for record in records]
            probability = (logits.float() / self.temperature).softmax(-1)
            probabilities.extend(probability[torch.arange(len(records), device=device), positive].cpu().tolist())
        return probabilities
